const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Set Business Context').first().json.generation_run_id, agent: 'positioning', positioning_output: parsed } }];

